import{_ as a,H as d,f as e,i as r}from"./chunks/framework.DPC7el8K.js";const p=JSON.parse('{"title":"📻 业余无线电设台与使用许可","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03-设台与许可.md","filePath":"guide/03-设台与许可.md","lastUpdated":1780450089000}'),o={name:"guide/03-设台与许可.md"};function l(i,t,h,n,s,_){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="📻-业余无线电设台与使用许可" tabindex="-1">📻 业余无线电设台与使用许可 <a class="header-anchor" href="#📻-业余无线电设台与使用许可" aria-label="Permalink to &quot;📻 业余无线电设台与使用许可&quot;">​</a></h1><hr><h3 id="业余无线电设备" tabindex="-1">业余无线电设备 <a class="header-anchor" href="#业余无线电设备" aria-label="Permalink to &quot;业余无线电设备&quot;">​</a></h3><p>常见的业余无线电台从形式上可分为：手持对讲机（手台）、车载电台、基地固定电台等。</p><h3 id="设备要求" tabindex="-1">设备要求 <a class="header-anchor" href="#设备要求" aria-label="Permalink to &quot;设备要求&quot;">​</a></h3><p>设置业余无线电台使用的无线电发射设备需满足以下任一条件：</p><ol><li>依法取得型号核准（型号核准证载明的频率范围包含业余业务频段）；</li><li>自制/改装/拼装等未取得型号核准的设备，需符合国家标准和国家无线电管理规定，且发射频率范围仅限于业余业务频段。</li></ol><h3 id="特殊人群限制" tabindex="-1">特殊人群限制 <a class="header-anchor" href="#特殊人群限制" aria-label="Permalink to &quot;特殊人群限制&quot;">​</a></h3><p>未成年人仅可设置、使用工作在 30-3000MHz 频段且最大发射功率不大于 25 瓦的业余无线电台。</p><h3 id="执照与呼号要求" tabindex="-1">执照与呼号要求 <a class="header-anchor" href="#执照与呼号要求" aria-label="Permalink to &quot;执照与呼号要求&quot;">​</a></h3><p>设置的业余无线电台需取得业余无线电台执照及电台呼号。</p><h3 id="操作类别与发射功率限制" tabindex="-1">操作类别与发射功率限制 <a class="header-anchor" href="#操作类别与发射功率限制" aria-label="Permalink to &quot;操作类别与发射功率限制&quot;">​</a></h3><p>不同操作类别对应的设台/使用权限如下：</p><table tabindex="0"><thead><tr><th>操作类别</th><th>频段范围</th><th>最大发射功率</th><th>备注</th></tr></thead><tbody><tr><td>A类</td><td>30-3000MHz</td><td>≤25 瓦</td><td>U/V段/6米</td></tr><tr><td>B类</td><td>30MHz以下</td><td>&lt;15 瓦</td><td>2024年3月1日前取得B类证书≤100 瓦</td></tr><tr><td>B类</td><td>30MHz以上</td><td>≤25 瓦</td><td>U/V段/6米</td></tr><tr><td>C类</td><td>30MHz以下</td><td>≤1000 瓦</td><td>-</td></tr><tr><td>C类</td><td>30MHz以上</td><td>≤25 瓦</td><td>U/V段/6米</td></tr></tbody></table><blockquote><p>引自《业余无线电台管理办法》第三十条。</p></blockquote>',15)])])}const u=a(o,[["render",l]]);export{p as __pageData,u as default};
